--- Returns the list of city names whose location cards are removed
--- for the given player count.
--- @param playerCount number  2, 3, or 4
--- @return table  array of city name strings
function BoardData.getRemovedCities(playerCount)
    local removed = {}
    if playerCount <= 3 then
        for _, c in ipairs(BoardData.tealCities) do
            removed[#removed + 1] = c
        end
    end
    if playerCount <= 2 then
        for _, c in ipairs(BoardData.blueCities) do
            removed[#removed + 1] = c
        end
    end
end

--- Returns the list of active merchant entries for the given player count.
--- A merchant is active when playerCount >= merchant.minPlayers.
--- @param playerCount number  2, 3, or 4
--- @return table  array of merchant entry tables
function BoardData.getActiveMerchants(playerCount)
    local active = {}
    for _, m in ipairs(BoardData.merchants) do
        if playerCount >= m.minPlayers then
            active[#active + 1] = m
        end
    end
end


-- ===== Module: Tile =====

Tile = {}

--- Create a new tile from BoardData.buildingCosts
--- @param industryType string  Constants.Industry value
--- @param level number  integer
--- @return table  A tile with all fields initialized
function Tile.new(industryType, level)
    local costData = BoardData.buildingCosts[industryType][level]
    if not costData then
        error(string.format("No building cost data for %s level %d", industryType, level))
    end

    -- Determine producesType based on industry
    local producesType = nil
    if industryType == Constants.Industry.COAL then
        producesType = Constants.Resource.COAL
    elseif industryType == Constants.Industry.IRON then
        producesType = Constants.Resource.IRON
    elseif industryType == Constants.Industry.BREWERY then
        producesType = Constants.Resource.BEER
    end

    -- Build the tile object with all fields
    local tile = {
        type = industryType,
        level = level,
        flipped = false,
        vp = costData.vp or 0,
        linkIcons = costData.linkIcons or 0,
        incomeSpaces = costData.incomeSpaces or 0,
        beerToSell = costData.beerToSell or 0,
        produces = costData.produces or 0,
        producesType = producesType,
        resources = {},
        noDevelop = costData.noDevelop or false,
        railOnly = costData.railOnly or false,
        cost = {
            money = costData.money or 0,
            coal = costData.coal or 0,
            iron = costData.iron or 0,
        },
    }

end

--- Create a tile and immediately fill its resources
--- Coal mines get N coal tokens, Iron works get N iron tokens, Breweries get N beer tokens
--- Breweries auto-flip on build
--- @param industryType string  Constants.Industry value
--- @param level number  integer
--- @return table  A tile with resources initialized and flipped state
function Tile.newWithResources(industryType, level)
    local tile = Tile.new(industryType, level)

    -- Fill resources if tile produces something
    if tile.produces > 0 and tile.producesType then
        for i = 1, tile.produces do
            tile.resources[i] = tile.producesType
        end
    end

    -- Breweries auto-flip on build
    if industryType == Constants.Industry.BREWERY then
        tile.flipped = true
    end

end


-- ===== Module: IncomeTrack =====

IncomeTrack = {}

-- Returns the income £ amount for a given level (level = income)
function IncomeTrack.levelToIncome(level)
    return level  -- income equals level number
end

-- Returns how many spaces are in a given level
function IncomeTrack.spacesPerLevel(level)
    if level <= 0 then
    elseif level <= 10 then
    elseif level <= 20 then
    else
    end
end

-- Advance N spaces forward from current position
-- Returns newLevel, newSpace
-- currentSpace is 0-indexed within the level (0 = first space, spacesPerLevel-1 = last)
function IncomeTrack.advanceSpaces(currentLevel, currentSpace, spaces)
    local level = currentLevel
    local space = currentSpace

    for _ = 1, spaces do
        space = space + 1

        -- Check if we crossed a level boundary
        if space >= IncomeTrack.spacesPerLevel(level) then
            level = level + 1
            space = 0
        end

        -- Cap at level 30, highest space
        if level > 30 then
            level = 30
            space = IncomeTrack.spacesPerLevel(30) - 1
            break
        end
    end

    return level, space
end

-- Decrease N levels (for loans). Land on highest space of new level.
-- Returns newLevel, newSpace
-- Cannot go below -10
function IncomeTrack.decreaseLevels(currentLevel, currentSpace, levels)
    local newLevel = math.max(-10, currentLevel - levels)
    local newSpace = IncomeTrack.spacesPerLevel(newLevel) - 1
    return newLevel, newSpace
end

-- Can the player take a loan? (level - penalty >= -10)
function IncomeTrack.canLoan(currentLevel)
    return (currentLevel - Constants.LOAN_INCOME_PENALTY) >= -10
end


-- ===== Module: GameState =====

GameState = {}

-- ============================================================
-- Internal helpers
-- ============================================================

--- Build the unbuiltTiles table for a single player.
--- Each industry type has an ordered stack (lowest level first).
--- We create `count` copies of Tile.new(type, level) per level entry.
local function buildUnbuiltTiles()
    local tiles = {}
    for industryType, levels in pairs(BoardData.buildingCosts) do
        tiles[industryType] = {}
        -- Collect all levels first so we can sort them
        local sortedLevels = {}
        for level, _ in pairs(levels) do
            sortedLevels[#sortedLevels + 1] = level
        end
        table.sort(sortedLevels)

        for _, level in ipairs(sortedLevels) do
            local costData = levels[level]
            local count = costData.count or 1
            for _ = 1, count do
                tiles[industryType][#tiles[industryType] + 1] = Tile.new(industryType, level)
            end
        end
    end
end

--- Build the board.cities table: deep copy + add occupant/tile fields,
--- and remove cities that are excluded for this player count.
local function buildBoardCities(playerCount)
    local removedSet = {}
    for _, name in ipairs(BoardData.getRemovedCities(playerCount)) do
        removedSet[name] = true
    end

    local cities = {}
    for cityName, cityData in pairs(BoardData.cities) do
        if not removedSet[cityName] then
            local city = helpers.deepCopy(cityData)
            -- Add occupant/tile fields to every slot
            if city.slots then
                for _, slot in ipairs(city.slots) do
                    slot.occupant = nil
                    slot.tile     = nil
                end
            end
            cities[cityName] = city
        end
    end
    return cities, removedSet
end

--- Build the board.links table: deep copy + add owner/tileGUID fields,
--- removing any link that connects to a removed city.
local function buildBoardLinks(removedSet)
    local links = {}
    for linkId, linkData in pairs(BoardData.links) do
        local skip = false
        for _, city in ipairs(linkData.cities) do
            if removedSet[city] then
                skip = true
                break
            end
        end
        if not skip then
            local link = helpers.deepCopy(linkData)
            link.owner    = nil
            link.tileGUID = nil
            links[linkId] = link
        end
    end
end

--- Build the flat slot index: slotId -> slot object reference.
local function buildSlotIndex(cities)
    local index = {}
    for _, city in pairs(cities) do
        if city.slots then
            for _, slot in ipairs(city.slots) do
                if slot.id then
                    index[slot.id] = slot
                end
            end
        end
    end
end

--- Build city index: slotId -> cityName for O(1) lookup.
local function buildCityIndex(cities)
    local index = {}
    for cityName, city in pairs(cities) do
        if city.slots then
            for _, slot in ipairs(city.slots) do
                if slot.id then
                    index[slot.id] = cityName
                end
            end
        end
    end
end

--- Build initial merchant state for active merchants.
--- Each active merchant city gets a `merchantBonus` field and `merchantSlots` table.
local function buildMerchants(playerCount, cities)
    local activeMerchants = BoardData.getActiveMerchants(playerCount)
    local merchantState = {}
    for _, m in ipairs(activeMerchants) do
        local slots = {}
        for i = 1, m.slots do
            slots[i] = { filled = false, tileGUID = nil }
        end
        merchantState[m.name] = {
            bonus  = helpers.deepCopy(m.bonus),
            slots  = slots,
        }
    end
end

-- ============================================================
-- Public API
-- ============================================================

--- Create a new game state for N players.
--- @param playerCount number  2, 3, or 4
--- @return table  full state object
function GameState.new(playerCount)
    assert(playerCount >= 2 and playerCount <= 4,
        "playerCount must be 2, 3, or 4, got: " .. tostring(playerCount))

    -- Turn order: first playerCount colors
    local turnOrder = {}
    for i = 1, playerCount do
        turnOrder[i] = Constants.ALL_COLORS[i]
    end

    -- Players
    local players = {}
    for i = 1, playerCount do
        local color = Constants.ALL_COLORS[i]
        players[color] = {
            color              = color,
            money              = Constants.INITIAL_MONEY,
            incomeLevel        = Constants.INITIAL_INCOME,
            incomeSpace        = 0,
            vp                 = 0,
            spentThisRound     = 0,
            linksRemaining     = Constants.INITIAL_LINKS,
            hasWilds           = false,
            handSize           = Constants.INITIAL_HAND_SIZE,
            scoutUsedThisRound = false,
            unbuiltTiles       = buildUnbuiltTiles(),
        }
    end

    -- Board
    local cities, removedSet = buildBoardCities(playerCount)
    local links              = buildBoardLinks(removedSet)
    local slotIndex          = buildSlotIndex(cities)
    local cityIndex          = buildCityIndex(cities)
    local merchants          = buildMerchants(playerCount, cities)

    return {
        era              = Constants.Era.CANAL,
        round            = 1,
        playerCount      = playerCount,
        currentPlayerIdx = 1,
        actionsRemaining = 1,   -- first round of canal era = 1 action

        players   = players,
        turnOrder = turnOrder,

        board = {
            cities    = cities,
            links     = links,
            merchants = merchants,
        },

        slotIndex  = slotIndex,
        cityIndex  = cityIndex,

        coalMarket = { supply = Constants.INITIAL_COAL_SUPPLY },
        ironMarket = { supply = Constants.INITIAL_IRON_SUPPLY },

        wildSupply = { location = Constants.WILD_SUPPLY_COUNT, industry = Constants.WILD_SUPPLY_COUNT },

        deckEmpty = false,

        lang = "en",
    }
end

--- Get player data by color.
--- Raises an error if the color is not in the game.
function GameState.getPlayer(state, color)
    local p = state.players[color]
    if not p then error("Invalid player color: " .. tostring(color)) end
end

--- Get a slot by its ID string.  O(1) via slotIndex.
function GameState.getSlot(state, slotId)
    return state.slotIndex[slotId]
end

--- Get the city name for a given slot ID.  O(1) via cityIndex.
function GameState.getCityForSlot(state, slotId)
    return state.cityIndex[slotId]
end

--- Deduct one card from a player's hand (playing a card).
function GameState.playCard(state, color)
    local p = GameState.getPlayer(state, color)
    p.handSize = math.max(0, (p.handSize or 0) - 1)
end

--- Deduct money from a player and record spending for turn-order purposes.
function GameState.spendMoney(state, color, amount)
    local p = GameState.getPlayer(state, color)
    p.money          = p.money - amount
    p.spentThisRound = p.spentThisRound + amount
end

--- Give money to a player.
function GameState.gainMoney(state, color, amount)
    local p = GameState.getPlayer(state, color)
    p.money = p.money + amount
end

--- Reset per-round tracking fields for all players at the start of a new round.
function GameState.resetRoundSpending(state)
    for _, p in pairs(state.players) do
        p.spentThisRound     = 0
        p.scoutUsedThisRound = false
    end
end

--- Return the color of the player whose turn it currently is.
function GameState.getCurrentPlayerColor(state)
    return state.turnOrder[state.currentPlayerIdx]
end

--- Return true when we are in round 1 of the canal era (only 1 action per player).
function GameState.isFirstRound(state)
    return state.era == Constants.Era.CANAL and state.round == 1
end

--- Call fn(cityName, slot, slotIndex) for every industry slot on the board.
function GameState.forEachSlot(state, fn)
    for cityName, city in pairs(state.board.cities) do
        if city.slots then
            for i, slot in ipairs(city.slots) do
                fn(cityName, slot, i)
            end
        end
    end
end

--- Count how many slots in a city are currently occupied.
--- Used for the canal-era "max one building per city" rule.
function GameState.countBuildingsInCity(state, cityName)
    local count = 0
    local city = state.board.cities[cityName]
    if city and city.slots then
        for _, slot in ipairs(city.slots) do
            if slot.occupant then count = count + 1 end
        end
    end
end

--- Return true if the player has at least one building or link on the board.
function GameState.hasPresenceOnBoard(state, color)
    -- Check buildings (direct loop for early exit)
    for _, city in pairs(state.board.cities) do
        if city.slots then
            for _, slot in ipairs(city.slots) do
                if slot.occupant == color then return true end
            end
        end
    end
    -- Check links
    for _, link in pairs(state.board.links) do
        if link.owner == color then return true end
    end
end

--- Serialize the entire state to a JSON string.
--- Uses the TTS global JSON object when available; returns "" otherwise.
function GameState.serialize(state)
    if JSON then
        return JSON.encode(state)
    end
    return ""
end

--- Deserialize a JSON string back to a state table.
--- Uses the TTS global JSON object when available; returns nil otherwise.
function GameState.deserialize(jsonStr)
    if JSON then
        return JSON.decode(jsonStr)
    end
end


-- ===== Module: Network =====

Network = {}

-- ============================================================
-- Internal helpers
-- ============================================================

-- Set of merchant city names for fast O(1) lookup (derived from BoardData)
local MERCHANT_CITIES = {}
for _, m in ipairs(BoardData.merchants) do
    MERCHANT_CITIES[m.name] = true
end

--- BFS over all placed links starting from `startCity`.
--- Calls `visitor(cityName, distance)` for every reachable city
--- (including the start, at distance 0).
--- `visitor` may return true to stop traversal early.
--- @param state table
--- @param startCity string
--- @param visitor function(cityName, distance) -> bool|nil
local function bfsAllLinks(state, startCity, visitor)
    if not state.board.cities[startCity] then return end

    local visited = { [startCity] = true }
    -- queue entries: { city = string, dist = number }
    local queue   = { { city = startCity, dist = 0 } }
    local head    = 1

    while head <= #queue do
        local entry = queue[head]
        head = head + 1

        if visitor(entry.city, entry.dist) then return end

        local adjLinks = BoardData.adjacency[entry.city] or {}
        for _, linkId in ipairs(adjLinks) do
            local link = state.board.links[linkId]
            -- Only traverse placed (owned) links
            if link and link.owner then
                local linkData = BoardData.links[linkId]
                for _, neighbor in ipairs(linkData.cities) do
                    if not visited[neighbor] then
                        -- Only visit cities that exist in the current game state
                        if state.board.cities[neighbor] then
                            visited[neighbor] = true
                            queue[#queue + 1] = { city = neighbor, dist = entry.dist + 1 }
                        end
                    end
                end
            end
        end
    end
end

--- BFS over only the given player's placed links, starting from `startCity`.
--- Calls `visitor(cityName)` for every reachable city (including start).
--- Also includes any city that has the player's building, even without links.
--- @param state table
--- @param color string
--- @param startCity string
--- @param visitor function(cityName)
local function bfsPlayerLinks(state, color, startCity, visitor)
    if not state.board.cities[startCity] then return end

    local visited = { [startCity] = true }
    local queue   = { startCity }
    local head    = 1

    while head <= #queue do
        local city = queue[head]
        head = head + 1

        visitor(city)

        local adjLinks = BoardData.adjacency[city] or {}
        for _, linkId in ipairs(adjLinks) do
            local link = state.board.links[linkId]
            if link and link.owner == color then
                local linkData = BoardData.links[linkId]
                for _, neighbor in ipairs(linkData.cities) do
                    if not visited[neighbor] then
                        if state.board.cities[neighbor] then
                            visited[neighbor] = true
                            queue[#queue + 1] = neighbor
                        end
                    end
                end
            end
        end
    end
end

-- ============================================================
-- Public API
-- ============================================================

--- Get the set of cities reachable by a player's network.
--- A city is "in network" if it has the player's building OR is adjacent to
--- a link owned by the player (and reachable via their link network).
---
--- Algorithm:
---   1. Seed with every city that already has the player's building.
---   2. BFS from each seed city, following only the player's links,
---      collecting all reachable cities.
---
--- @param state table
--- @param color string
--- @return table  { [cityName] = true, ... }
function Network.getPlayerNetwork(state, color)
    local network = {}

    -- Seed set: cities where the player has a building
    local seeds = {}
    for cityName, city in pairs(state.board.cities) do
        if city.slots then
            for _, slot in ipairs(city.slots) do
                if slot.occupant == color then
                    seeds[cityName] = true
                    break
                end
            end
        end
    end

    -- Also seed cities at either end of the player's links
    for linkId, link in pairs(state.board.links) do
        if link.owner == color then
            local linkData = BoardData.links[linkId]
            for _, cityName in ipairs(linkData.cities) do
                if state.board.cities[cityName] then
                    seeds[cityName] = true
                end
            end
        end
    end

    -- BFS from every seed city, following player's links
    for seedCity, _ in pairs(seeds) do
        if not network[seedCity] then
            bfsPlayerLinks(state, color, seedCity, function(cityName)
                network[cityName] = true
            end)
        end
    end

end

--- Check if a specific city is in a player's network.
--- @param state table
--- @param color string
--- @param cityName string
--- @return boolean
function Network.isInNetwork(state, color, cityName)
    return Network.getPlayerNetwork(state, color)[cityName] == true
end

--- Check if a city is connected to any active merchant via ANY player's links.
--- A merchant city is active when a merchant tile has been placed there.
--- @param state table
--- @param color string  (unused; kept for API symmetry — path uses any links)
--- @param cityName string
--- @return boolean
function Network.isConnectedToMerchant(state, color, cityName)
    local found = false
    bfsAllLinks(state, cityName, function(reachedCity, _distance)
        if MERCHANT_CITIES[reachedCity] then
            -- Check the merchant city is actually in play (has an entry in merchants)
            if state.board.merchants[reachedCity] then
                found = true
                return true  -- stop BFS
            end
        end
    end)
end

--- Find a connected merchant city reachable from cityName via ANY player's links.
--- Returns the merchant name, or nil if none found.
---
--- @param state table
--- @param cityName string
--- @return string|nil  merchant city name
function Network.findConnectedMerchant(state, cityName)
    local merchantName = nil
    bfsAllLinks(state, cityName, function(reachedCity, _distance)
        if MERCHANT_CITIES[reachedCity] then
            if state.board.merchants[reachedCity] then
                merchantName = reachedCity
                return true  -- stop BFS
            end
        end
    end)
end

--- Find the nearest coal source connected to a city, following ANY player's links.
--- "Nearest" means fewest links traversed.
--- If multiple sources are at the same distance, all are returned.
---
--- @param state table
--- @param cityName string
--- @return table|nil  list of { cityName, slotId, slot } entries, or nil if none found
function Network.findNearestCoal(state, cityName)
    local results   = nil
    local bestDist  = math.huge

    bfsAllLinks(state, cityName, function(reachedCity, distance)
        -- Stop expanding once we've gone past the best distance found
        if distance > bestDist then
            return true  -- stop BFS early
        end

        local city = state.board.cities[reachedCity]
        if city and city.slots then
            for _, slot in ipairs(city.slots) do
                if slot.tile
                    and slot.tile.type == Constants.Industry.COAL
                    and not slot.tile.flipped
                    and #slot.tile.resources > 0
                then
                    if distance < bestDist then
                        bestDist = distance
                        results  = {}
                    end
                    results[#results + 1] = {
                        cityName = reachedCity,
                        slotId   = slot.id,
                        slot     = slot,
                    }
                end
            end
        end
    end)

end

--- Find all iron sources on the board (no connection required).
--- Returns every unflipped iron works with at least one iron resource.
---
--- @param state table
--- @return table  list of { cityName, slotId, slot }
function Network.findIronSources(state)
    local results = {}
    for cityName, city in pairs(state.board.cities) do
        if city.slots then
            for _, slot in ipairs(city.slots) do
                if slot.tile
                    and slot.tile.type == Constants.Industry.IRON
                    and not slot.tile.flipped
                    and #slot.tile.resources > 0
                then
                    results[#results + 1] = {
                        cityName = cityName,
                        slotId   = slot.id,
                        slot     = slot,
                    }
                end
            end
        end
    end
end

--- Find all beer sources available for an action performed by `color` at `cityName`.
---
--- Rules:
---   1. Own breweries: available regardless of connection.
---   2. Other players' breweries: must be reachable from cityName via any placed link.
---   3. Merchant beer: if merchantName is provided, that merchant's beer (if any).
---
--- @param state table
--- @param color string
--- @param cityName string
--- @param merchantName string|nil  name of the merchant being sold to (optional)
--- @return table  list of { cityName, slotId, slot, owner, isMerchantBeer }
function Network.findBeerSources(state, color, cityName, merchantName)
    local results = {}

    -- Helper: add a brewery slot to results if it has beer
    local function addBrewery(bCityName, slot, owner, isMerchantBeer)
        if slot.tile
            and slot.tile.type == Constants.Industry.BREWERY
            and slot.tile.flipped   -- breweries flip on build; flipped = active
            and #slot.tile.resources > 0
        then
            results[#results + 1] = {
                cityName      = bCityName,
                slotId        = slot.id,
                slot          = slot,
                owner         = owner,
                isMerchantBeer = isMerchantBeer or false,
            }
        end
    end

    -- 1. Own breweries (no connection needed)
    for bCityName, city in pairs(state.board.cities) do
        if city.slots then
            for _, slot in ipairs(city.slots) do
                if slot.occupant == color then
                    addBrewery(bCityName, slot, color, false)
                end
            end
        end
    end

    -- 2. Other players' breweries reachable via any placed link from cityName
    local reachable = {}
    bfsAllLinks(state, cityName, function(reachedCity, _)
        reachable[reachedCity] = true
    end)

    for bCityName, city in pairs(state.board.cities) do
        if city.slots then
            for _, slot in ipairs(city.slots) do
                if slot.occupant and slot.occupant ~= color and reachable[bCityName] then
                    addBrewery(bCityName, slot, slot.occupant, false)
                end
            end
        end
    end

    -- 3. Merchant beer (only when selling to a specific merchant)
    if merchantName then
        local merchant = state.board.merchants[merchantName]
        if merchant and merchant.beer and merchant.beer > 0 then
            -- Represent merchant beer as a synthetic entry (no real slot)
            results[#results + 1] = {
                cityName       = merchantName,
                slotId         = nil,
                slot           = nil,
                owner          = merchantName,
                isMerchantBeer = true,
            }
        end
    end

end

--- Check if there is a path from cityName to any merchant city
--- via any placed links (for coal market access).
---
--- @param state table
--- @param color string  (unused; path uses any player's links)
--- @param cityName string
--- @return boolean
function Network.hasMarketConnection(state, color, cityName)
    return Network.isConnectedToMerchant(state, color, cityName)
end

--- Parse a link ID of the form "CityA-CityB" and return both city names.
--- Falls back to splitting on the first "-" that separates known city names.
---
--- @param linkId string
--- @return string, string  cityA, cityB
function Network.getLinkCities(linkId)
    -- First try BoardData directly (authoritative source)
    local linkData = BoardData.links[linkId]
    if linkData and linkData.cities then
        return linkData.cities[1], linkData.cities[2]
    end

    -- Fallback: brute-force split at every "-" position
    -- to find a split where both parts are known city names
    local len = #linkId
    for i = 2, len - 1 do
        if linkId:sub(i, i) == "-" then
            local a = linkId:sub(1, i - 1)
            local b = linkId:sub(i + 1)
            if BoardData.cities[a] and BoardData.cities[b] then
                return a, b
            end
        end
    end

    -- Last resort: return raw split on first "-"
    local first, second = linkId:match("^([^%-]+)%-(.+)$")
    return first or linkId, second or ""
end


-- ===== Module: Market =====

Market = {}

-- ============================================================
-- Price Lookup Logic
-- ============================================================

--- Get current price for a resource type from market.
--- resourceType: Constants.Resource.COAL or Constants.Resource.IRON
--- The price is determined by the NEXT cube position (the cheapest empty space).
--- When supply = 0, return max price (coal=8, iron=6).
function Market.getPrice(state, resourceType)
    local marketSupply = Market.getMarketSupply(state, resourceType)
    if not marketSupply then return 0 end

    local supply = marketSupply.supply
    local track = Market.getTrack(resourceType)
    local trackLength = (#track)

    -- When supply is 0, return max price (virtual unlimited supply)
    if supply == 0 then
        return Market.getMaxPrice(resourceType)
    end

    -- Price is determined by the position of the leftmost (next) cube
    -- Position = trackLength - supply + 1
    local position = trackLength - supply + 1
    if position < 1 then position = 1 end

    return track[position]
end

-- ============================================================
-- Market Transactions
-- ============================================================

--- Buy N resources from market, deducting money from player.
--- For each unit: get current price, deduct from player, decrease market supply.
--- Returns total cost paid.
function Market.buyFromMarket(state, color, resourceType, count)
    local totalCost = 0

    for i = 1, count do
        local price = Market.getPrice(state, resourceType)
        totalCost = totalCost + price

        -- Deduct money from player
        GameState.spendMoney(state, color, price)

        -- Decrease market supply by 1
        local marketSupply = Market.getMarketSupply(state, resourceType)
        if marketSupply then
            marketSupply.supply = marketSupply.supply - 1
        end
    end

end

--- Return a resource to the market (when consumed from a building).
--- In Brass: Birmingham, when coal/iron is consumed, the cube goes back to market.
--- Fills lowest empty space on the track.
--- If track is full, resource overflows to general supply (lost).
function Market.returnToMarket(state, resourceType, count)
    local marketSupply = Market.getMarketSupply(state, resourceType)
    if not marketSupply then return end

    local track = Market.getTrack(resourceType)
    local trackMax = (#track)

    -- Increase supply, capped at track max
    marketSupply.supply = marketSupply.supply + count
    if marketSupply.supply > trackMax then
        marketSupply.supply = trackMax
    end
end

-- ============================================================
-- Market State Accessors
-- ============================================================

--- Get the market supply table for a resource type.
function Market.getMarketSupply(state, resourceType)
    if resourceType == Constants.Resource.COAL then
        return state.coalMarket
    elseif resourceType == Constants.Resource.IRON then
        return state.ironMarket
    end
end

--- Get the track data for a resource type.
function Market.getTrack(resourceType)
    if resourceType == Constants.Resource.COAL then
        return BoardData.coalMarketTrack
    elseif resourceType == Constants.Resource.IRON then
        return BoardData.ironMarketTrack
    end
end

--- Get max price for a resource (when market is empty, virtual unlimited supply).
function Market.getMaxPrice(resourceType)
    if resourceType == Constants.Resource.COAL then return 8 end
    if resourceType == Constants.Resource.IRON then return 6 end
end


-- ===== Module: TurnManager =====

TurnManager = {}

-- Get number of actions for current turn
-- Canal era first round = 1 action; all other cases = 2 actions
function TurnManager.getActionsThisTurn(state)
    if GameState.isFirstRound(state) then return 1 end
end

-- Execute income phase: each player receives money equal to their income level
-- Negative income = pay the bank; shortfall = lose 1 VP per £ owed
function TurnManager.incomePhase(state)
    for _, color in ipairs(state.turnOrder) do
        local p = GameState.getPlayer(state, color)
        local income = IncomeTrack.levelToIncome(p.incomeLevel)
        if income >= 0 then
            GameState.gainMoney(state, color, income)
        else
            local owed = math.abs(income)
            if p.money >= owed then
                p.money = p.money - owed
            else
                local shortfall = owed - p.money
                p.money = 0
                p.vp = p.vp - shortfall  -- lose 1 VP per £ short
            end
        end
    end
end

-- Reorder turn order by spending (ascending, stable sort)
-- Players who spent less go first; ties preserve previous order
function TurnManager.reorderTurnOrder(state)
    helpers.stableSort(state.turnOrder, function(a, b)
        return GameState.getPlayer(state, a).spentThisRound
             < GameState.getPlayer(state, b).spentThisRound
    end)
end

-- Advance to next player
function TurnManager.nextPlayer(state)
    state.currentPlayerIdx = state.currentPlayerIdx + 1
    if state.currentPlayerIdx > #state.turnOrder then
        state.currentPlayerIdx = 1
    end
end

-- Start a new round
function TurnManager.startNewRound(state)
    TurnManager.reorderTurnOrder(state)
    GameState.resetRoundSpending(state)
    state.round = state.round + 1
    state.currentPlayerIdx = 1
    state.actionsRemaining = TurnManager.getActionsThisTurn(state)
end

-- Called after a player completes one action
function TurnManager.endAction(state)
    state.actionsRemaining = state.actionsRemaining - 1
    if state.actionsRemaining <= 0 then
        -- Current player's turn is over
        -- Draw cards back to 8 (handled by TTS layer in Phase 2)
        local p = GameState.getPlayer(state, GameState.getCurrentPlayerColor(state))
        p.handSize = 8  -- reset hand size (card draw handled by TTS)

        TurnManager.nextPlayer(state)
        if state.currentPlayerIdx == 1 then
            -- All players completed their turns — start new round
            TurnManager.startNewRound(state)
        else
            state.actionsRemaining = TurnManager.getActionsThisTurn(state)
        end
    end
end


-- ===== Module: Validation =====

Validation = {}

-- ============================================================
-- Internal helpers
-- ============================================================

local function ok()
    return { valid = true, reason = "" }
end

local function fail(reason)
    return { valid = false, reason = reason }
end

--- Count total coal cubes on all unflipped coal-mine buildings on the board.
local function totalCoalOnBoard(state)
    local total = 0
    GameState.forEachSlot(state, function(_, slot)
        if slot.tile
            and slot.tile.type == Constants.Industry.COAL
            and not slot.tile.flipped
        then
            total = total + #slot.tile.resources
        end
    end)
end

--- Count total iron cubes on all unflipped iron-works buildings on the board.
local function totalIronOnBoard(state)
    local total = 0
    GameState.forEachSlot(state, function(_, slot)
        if slot.tile
            and slot.tile.type == Constants.Industry.IRON
            and not slot.tile.flipped
        then
            total = total + #slot.tile.resources
        end
    end)
end


--- Count how many coal cubes are reachable from cityName (via any placed links,
--- including coal at the city itself) plus market supply.
--- Returns boardCoal, marketCoal.
local function countCoalAvailable(state, cityName)
    local boardCoal = 0
    local visited   = {}

    local function bfs(city)
        if visited[city] then return end
        visited[city] = true
        local cityData = state.board.cities[city]
        if cityData and cityData.slots then
            for _, slot in ipairs(cityData.slots) do
                if slot.tile
                    and slot.tile.type == Constants.Industry.COAL
                    and not slot.tile.flipped
                then
                    boardCoal = boardCoal + #slot.tile.resources
                end
            end
        end
        local adjLinks = BoardData.adjacency[city] or {}
        for _, linkId in ipairs(adjLinks) do
            local link = state.board.links[linkId]
            if link and link.owner then
                local linkData = BoardData.links[linkId]
                for _, neighbor in ipairs(linkData.cities) do
                    if state.board.cities[neighbor] then
                        bfs(neighbor)
                    end
                end
            end
        end
    end

    bfs(cityName)

    local marketCoal = state.coalMarket.supply
    return boardCoal, marketCoal
end

--- Count total iron available anywhere on the board (no connection needed)
--- plus market supply.
local function countIronAvailable(state)
    local boardIron = 0
    local sources = Network.findIronSources(state)
    for _, src in ipairs(sources) do
        boardIron = boardIron + #src.slot.tile.resources
    end
    local marketIron = state.ironMarket.supply
    return boardIron, marketIron
end

-- ============================================================
-- 1. canBuild
-- ============================================================

--- Can player build at a specific location?
--- params: { cardType, location, industryType, level, slotId }
function Validation.canBuild(state, color, params)
    local cardType     = params.cardType
    local location     = params.location     -- city name from card
    local industryType = params.industryType
    local level        = params.level
    local slotId       = params.slotId

    local player = GameState.getPlayer(state, color)

    -- ---- 1. Resolve slot ----
    local slot = GameState.getSlot(state, slotId)
    if not slot then
        return fail("Slot '" .. tostring(slotId) .. "' does not exist")
    end

    local cityName = GameState.getCityForSlot(state, slotId)
    if not cityName then
        return fail("Cannot determine city for slot '" .. tostring(slotId) .. "'")
    end

    -- Confirm the city exists in this game state
    if not state.board.cities[cityName] then
        return fail("City '" .. cityName .. "' is not in play")
    end

    -- ---- 2. Rail-only check (canal era) ----
    local costData = BoardData.buildingCosts[industryType]
                     and BoardData.buildingCosts[industryType][level]
    if not costData then
        return fail("No data for " .. tostring(industryType) .. " level " .. tostring(level))
    end

    if costData.railOnly and state.era == Constants.Era.CANAL then
        return fail(industryType .. " level " .. level .. " cannot be built in the canal era")
    end

    -- ---- 3. Canal era: max 1 building per city ----
    if state.era == Constants.Era.CANAL then
        local count = GameState.countBuildingsInCity(state, cityName)
        -- The slot must be empty for this check; we will allow overbuilding below
        -- but not placing a second building in a different empty slot in the same city.
        if slot.occupant == nil and count >= 1 then
            return fail("Cannot build in " .. cityName .. ": already has a building (canal era)")
        end
    end

    -- ---- 4. Slot occupancy / overbuilding ----
    if slot.occupant then
        -- Slot is occupied — check overbuilding rules
        if slot.occupant == color then
            -- Own tile: can overbuild any unflipped tile with a higher level of ANY industry
            if slot.tile and slot.tile.flipped then
                return fail("Cannot overbuild your own flipped tile")
            end
            if slot.tile and level <= slot.tile.level then
                return fail("Overbuilding own tile requires a higher level tile")
            end
        else
            -- Opponent's tile: only coal or iron, resources must be 0 everywhere
            if slot.tile then
                local tileType = slot.tile.type
                if tileType ~= Constants.Industry.COAL and tileType ~= Constants.Industry.IRON then
                    return fail("Cannot overbuild opponent's " .. tostring(tileType) .. " tile")
                end
                -- Check that 0 of that resource type exist on all buildings AND market
                if tileType == Constants.Industry.COAL then
                    if totalCoalOnBoard(state) > 0 then
                        return fail("Cannot overbuild opponent's coal mine: coal still available on board")
                    end
                    if state.coalMarket.supply > 0 then
                        return fail("Cannot overbuild opponent's coal mine: coal still available in market")
                    end
                elseif tileType == Constants.Industry.IRON then
                    if totalIronOnBoard(state) > 0 then
                        return fail("Cannot overbuild opponent's iron works: iron still available on board")
                    end
                    if state.ironMarket.supply > 0 then
                        return fail("Cannot overbuild opponent's iron works: iron still available in market")
                    end
                end
            end
        end
    end

    -- ---- 5. Slot industry type matches what player wants to build ----
    if slot.type and slot.type ~= industryType then
        return fail("Slot accepts " .. tostring(slot.type) .. " but you want to build " .. tostring(industryType))
    end

    -- ---- 6. Player has the tile available ----
    local stack = player.unbuiltTiles[industryType]
    if not stack or #stack == 0 then
        return fail("No " .. industryType .. " tiles remaining on your player board")
    end
    -- Must build the lowest-level tile first
    if stack[1].level ~= level then
        return fail("Must build lowest available " .. industryType
                    .. " level (" .. stack[1].level .. "), not level " .. level)
    end

    -- ---- 7. Network / card type check ----
    local hasPresence = GameState.hasPresenceOnBoard(state, color)

    if cardType == Constants.CardType.LOCATION or cardType == Constants.CardType.WILD_LOCATION then
        -- Location card: build at matching city regardless of network
        if location ~= cityName then
            return fail("Location card for '" .. tostring(location)
                        .. "' cannot be used to build in '" .. cityName .. "'")
        end
        -- No network check needed for location cards

    elseif cardType == Constants.CardType.INDUSTRY or cardType == Constants.CardType.WILD_INDUSTRY then
        -- Industry card: city must be in player's network
        -- Exception: if player has NO presence on board, can build anywhere
        if hasPresence then
            if not Network.isInNetwork(state, color, cityName) then
                return fail("'" .. cityName .. "' is not in your network (industry card requires network connection)")
            end
        end
        -- No location restriction — just industry type match (already done via slot.type)
    else
        return fail("Unknown card type: " .. tostring(cardType))
    end

    -- ---- 8. Money check ----
    if player.money < costData.money then
        return fail("Not enough money: need £" .. costData.money .. ", have £" .. player.money)
    end

    -- ---- 9. Coal resource check ----
    local coalNeeded = costData.coal or 0
    if coalNeeded > 0 then
        local boardCoal, marketCoal = countCoalAvailable(state, cityName)
        local totalCoal = boardCoal + marketCoal
        if totalCoal < coalNeeded then
            return fail("Not enough coal: need " .. coalNeeded .. ", only " .. totalCoal .. " available")
        end
    end

    -- ---- 10. Iron resource check ----
    local ironNeeded = costData.iron or 0
    if ironNeeded > 0 then
        local boardIron, marketIron = countIronAvailable(state)
        local totalIron = boardIron + marketIron
        if totalIron < ironNeeded then
            return fail("Not enough iron: need " .. ironNeeded .. ", only " .. totalIron .. " available")
        end
    end

    return ok()
end

-- ============================================================
-- 2. canNetwork
-- ============================================================

--- Can player build a network link?
--- params: { linkId, double (bool, for double rail) }
function Validation.canNetwork(state, color, params)
    local linkId   = params.linkId
    local isDouble = params.double or false

    local player = GameState.getPlayer(state, color)
    local era    = state.era

    -- ---- 1. Link exists ----
    local link     = state.board.links[linkId]
    local linkData = BoardData.links[linkId]
    if not link or not linkData then
        return fail("Link '" .. tostring(linkId) .. "' does not exist")
    end

    -- ---- 2. Link has no owner ----
    if link.owner then
        return fail("Link '" .. linkId .. "' is already owned by " .. tostring(link.owner))
    end

    -- ---- 3. Era type match ----
    local linkTypes = linkData.types
    local eraType   = era  -- Constants.Era.CANAL or Constants.Era.RAIL
    local eraOk     = false
    for _, t in ipairs(linkTypes) do
        if t == eraType then eraOk = true; break end
    end
    if not eraOk then
        return fail("Link '" .. linkId .. "' is not available in the " .. era .. " era")
    end

    -- ---- 4. Link must touch player's network ----
    -- Exception: if player has no presence at all, first link can go anywhere
    local hasPresence = GameState.hasPresenceOnBoard(state, color)
    if hasPresence then
        local cityA, cityB = linkData.cities[1], linkData.cities[2]
        local network      = Network.getPlayerNetwork(state, color)
        if not network[cityA] and not network[cityB] then
            return fail("Link '" .. linkId .. "' does not connect to your network")
        end
    end

    -- ---- 5. Cost and resource checks ----
    if era == Constants.Era.CANAL then
        -- Canal: £CANAL cost, no resources
        if player.money < Constants.LinkCost.CANAL then
            return fail("Not enough money for canal link: need £" .. Constants.LinkCost.CANAL .. ", have £" .. player.money)
        end

    elseif era == Constants.Era.RAIL then
        if isDouble then
            -- Double rail: £DOUBLE_RAIL + 2 coal + 1 beer (covers 2 links)
            if player.money < Constants.LinkCost.DOUBLE_RAIL then
                return fail("Not enough money for double rail: need £" .. Constants.LinkCost.DOUBLE_RAIL .. ", have £" .. player.money)
            end
            -- Need 2 coal
            local cityA = linkData.cities[1]
            local boardCoal, marketCoal = countCoalAvailable(state, cityA)
            local totalCoal = boardCoal + marketCoal
            if totalCoal < 2 then
                return fail("Not enough coal for double rail: need 2, only " .. totalCoal .. " available")
            end
            -- Need 1 beer
            local beerSources = Network.findBeerSources(state, color, cityA, nil)
            local totalBeer = #beerSources
            if totalBeer < 1 then
                return fail("Not enough beer for double rail: need 1, none available")
            end
        else
            -- Single rail: £SINGLE_RAIL + 1 coal
            if player.money < Constants.LinkCost.SINGLE_RAIL then
                return fail("Not enough money for rail link: need £" .. Constants.LinkCost.SINGLE_RAIL .. ", have £" .. player.money)
            end
            local cityA = linkData.cities[1]
            local boardCoal, marketCoal = countCoalAvailable(state, cityA)
            local totalCoal = boardCoal + marketCoal
            if totalCoal < 1 then
                return fail("Not enough coal for rail link: need 1, only " .. totalCoal .. " available")
            end
        end
    end

    return ok()
end

-- ============================================================
-- 3. canSell
-- ============================================================

--- Can player sell?
--- params: { slotId } or { slotIds } for multi-sell
function Validation.canSell(state, color, params)
    -- Normalise to a list of slotIds
    local slotIds
    if params.slotIds then
        slotIds = params.slotIds
    elseif params.slotId then
        slotIds = { params.slotId }
    else
        return fail("No slotId or slotIds provided")
    end

    if #slotIds == 0 then
        return fail("No slots specified")
    end

    for _, slotId in ipairs(slotIds) do
        local slot = GameState.getSlot(state, slotId)
        if not slot then
            return fail("Slot '" .. tostring(slotId) .. "' does not exist")
        end

        -- ---- 1. Must be occupied by this player ----
        if slot.occupant ~= color then
            return fail("Slot '" .. slotId .. "' is not owned by you")
        end

        local tile = slot.tile
        if not tile then
            return fail("Slot '" .. slotId .. "' has no tile")
        end

        -- ---- 2. Must be a sellable industry ----
        if not helpers.tableContains(Constants.SELLABLE_INDUSTRIES, tile.type) then
            return fail("'" .. tile.type .. "' is not a sellable industry")
        end

        -- ---- 3. Must not already be flipped ----
        if tile.flipped then
            return fail("Slot '" .. slotId .. "' is already sold (flipped)")
        end

        -- ---- 4. Must be connected to a merchant via network ----
        local cityName = GameState.getCityForSlot(state, slotId)
        if not cityName then
            return fail("Cannot determine city for slot '" .. slotId .. "'")
        end

        if not Network.isConnectedToMerchant(state, color, cityName) then
            return fail("'" .. cityName .. "' is not connected to any merchant city")
        end

        -- ---- 5. Beer check: enough beer for this tile ----
        local beerNeeded = tile.beerToSell or 0
        if beerNeeded > 0 then
            -- Find the merchant city this is connected to (first one found)
            local merchantName = Network.findConnectedMerchant(state, cityName)

            local beerSources = Network.findBeerSources(state, color, cityName, merchantName)
            -- Count total beer tokens across all sources
            local totalBeer = 0
            for _, src in ipairs(beerSources) do
                if src.isMerchantBeer then
                    -- Merchant beer: add merchant.beer count
                    local merchant = state.board.merchants[src.cityName]
                    if merchant and merchant.beer then
                        totalBeer = totalBeer + merchant.beer
                    else
                        totalBeer = totalBeer + 1  -- synthetic entry represents 1
                    end
                elseif src.slot and src.slot.tile then
                    totalBeer = totalBeer + #src.slot.tile.resources
                end
            end

            if totalBeer < beerNeeded then
                return fail("Not enough beer to sell '" .. tile.type
                            .. "': need " .. beerNeeded .. ", only " .. totalBeer .. " available")
            end
        end
    end

    return ok()
end

-- ============================================================
-- 4. canDevelop
-- ============================================================

--- Can player develop?
--- params: { count } (1 or 2 tiles to remove)
function Validation.canDevelop(state, color, params)
    local count = params.count or 1

    if count ~= 1 and count ~= 2 then
        return fail("Develop count must be 1 or 2, got " .. tostring(count))
    end

    local player = GameState.getPlayer(state, color)

    -- Find the N lowest-level developable tiles across all industry types.
    -- For each industry type: the first tile in the stack is lowest level.
    -- noDevelop tiles at the bottom of a stack must be skipped to the next one.

    -- Collect all candidate tiles: one (or two) per industry type,
    -- skipping noDevelop entries at the front of each stack.
    local candidates = {}

    for industryType, stack in pairs(player.unbuiltTiles) do
        -- Walk the stack from index 1 to find the first non-noDevelop tile
        for _, tile in ipairs(stack) do
            if not tile.noDevelop then
                candidates[#candidates + 1] = { industryType = industryType, tile = tile }
                break  -- only consider the lowest developable per industry type
            end
        end
    end

    if #candidates < count then
        return fail("Not enough developable tiles: need " .. count
                    .. " but only " .. #candidates .. " available")
    end

    -- ---- Iron check: need 1 iron per tile developed ----
    local boardIron, marketIron = countIronAvailable(state)
    local totalIron = boardIron + marketIron
    if totalIron < count then
        return fail("Not enough iron to develop: need " .. count .. ", only " .. totalIron .. " available")
    end

    return ok()
end

-- ============================================================
-- 5. canLoan
-- ============================================================

--- Can player take a loan?
function Validation.canLoan(state, color)
    local player = GameState.getPlayer(state, color)
    if not IncomeTrack.canLoan(player.incomeLevel) then
        return fail("Cannot take a loan: income level " .. player.incomeLevel
                    .. " would drop below -10")
    end
    return ok()
end

-- ============================================================
-- 6. canScout
-- ============================================================

--- Can player scout?
function Validation.canScout(state, color)
    local player = GameState.getPlayer(state, color)

    -- ---- 1. Must NOT already have wild cards ----
    if player.hasWilds then
        return fail("You already have wild cards in hand")
    end

    -- ---- 2. Must have at least 3 cards (1 to play + 2 to discard) ----
    -- handSize tracks how many cards the player currently holds
    if (player.handSize or 0) < 3 then
        return fail("Not enough cards to scout: need at least 3, have " .. (player.handSize or 0))
    end

    -- ---- 3. Wild supply must have at least 1 of each type ----
    if not state.wildSupply or (state.wildSupply.location or 0) < 1 then
        return fail("No wild location cards remaining in supply")
    end
    if (state.wildSupply.industry or 0) < 1 then
        return fail("No wild industry cards remaining in supply")
    end

    -- ---- 4. Player has not already scouted this round ----
    if player.scoutUsedThisRound then
        return fail("You have already used Scout this round")
    end

    return ok()
end


-- ===== Module: Actions =====

Actions = {}

-- ============================================================
-- Internal helpers
-- ============================================================

local function ok()
    return { success = true, error = "" }
end

local function fail(reason)
    return { success = false, error = reason }
end

--- Advance a player's income track by N spaces and update state.
local function advanceIncome(state, color, spaces)
    if spaces <= 0 then return end
    local player = GameState.getPlayer(state, color)
    local newLevel, newSpace = IncomeTrack.advanceSpaces(
        player.incomeLevel, player.incomeSpace, spaces)
    player.incomeLevel = newLevel
    player.incomeSpace = newSpace
end

--- Auto-flip a tile (coal/iron) when its resources are exhausted.
--- Awards income advancement to the tile's owner.
local function autoFlipIfEmpty(state, slot)
    local tile = slot.tile
    if not tile then return end
    if tile.flipped then return end
    -- Only auto-flip coal mines and iron works
    if tile.type ~= Constants.Industry.COAL and tile.type ~= Constants.Industry.IRON then
        return
    end
    if #tile.resources == 0 then
        tile.flipped = true
        -- Award income to the owner
        if slot.occupant then
            advanceIncome(state, slot.occupant, tile.incomeSpaces)
        end
    end
end

--- Consume up to `needed` coal from buildings connected to `cityName`.
--- Returns the number still needed after taking from buildings.
--- Consumed coal is returned to market.
local function consumeCoalFromBuildings(state, cityName, needed)
    local remaining = needed
    local sources = Network.findNearestCoal(state, cityName)
    while remaining > 0 do
        if not sources or #sources == 0 then break end
        -- Take one coal from the first source (nearest)
        local src = sources[1]
        local resources = src.slot.tile.resources
        if #resources > 0 then
            table.remove(resources, #resources)  -- remove last token
            Market.returnToMarket(state, Constants.Resource.COAL, 1)
            autoFlipIfEmpty(state, src.slot)
            remaining = remaining - 1
            -- If this source is exhausted, remove it from the list
            if #resources == 0 then
                table.remove(sources, 1)
            end
        else
            -- Source exhausted, remove and continue
            table.remove(sources, 1)
        end
        -- If all sources at this distance are exhausted, re-search for next nearest
        if #sources == 0 and remaining > 0 then
            sources = Network.findNearestCoal(state, cityName)
        end
    end
end

--- Consume up to `needed` iron from any iron works on the board.
--- Returns the number still needed after taking from buildings.
--- Consumed iron is returned to market.
local function consumeIronFromBuildings(state, needed)
    local remaining = needed
    local sources = Network.findIronSources(state)
    local srcIdx = 1
    while remaining > 0 do
        if srcIdx > #sources then break end
        local src = sources[srcIdx]
        local resources = src.slot.tile.resources
        if #resources > 0 then
            table.remove(resources, #resources)
            Market.returnToMarket(state, Constants.Resource.IRON, 1)
            autoFlipIfEmpty(state, src.slot)
            remaining = remaining - 1
            -- If this source is exhausted, move to the next
            if #resources == 0 then
                srcIdx = srcIdx + 1
            end
        else
            srcIdx = srcIdx + 1
        end
    end
end

--- Consume `needed` coal: buildings first, then market.
local function consumeCoal(state, color, cityName, needed)
    if needed <= 0 then return end
    local fromMarket = consumeCoalFromBuildings(state, cityName, needed)
    if fromMarket > 0 then
        Market.buyFromMarket(state, color, Constants.Resource.COAL, fromMarket)
    end
end

--- Consume `needed` iron: buildings first, then market.
local function consumeIron(state, color, needed)
    if needed <= 0 then return end
    local fromMarket = consumeIronFromBuildings(state, needed)
    if fromMarket > 0 then
        Market.buyFromMarket(state, color, Constants.Resource.IRON, fromMarket)
    end
end

--- Consume `needed` beer from available sources for an action at `cityName`.
--- Own breweries are used first, then connected others, then merchant beer.
--- Beer is not returned to market — it is simply removed.
--- `merchantName` is the merchant city being sold to (nil if not selling).
local function consumeBeer(state, color, cityName, needed, merchantName)
    if needed <= 0 then return end
    local remaining = needed
    local sources = Network.findBeerSources(state, color, cityName, merchantName)
    for _, src in ipairs(sources) do
        if remaining <= 0 then break end
        if src.isMerchantBeer then
            local merchant = state.board.merchants[src.cityName]
            if merchant and merchant.beer and merchant.beer > 0 then
                merchant.beer = merchant.beer - 1
                remaining = remaining - 1
            end
        elseif src.slot and src.slot.tile then
            local resources = src.slot.tile.resources
            while remaining > 0 and #resources > 0 do
                table.remove(resources, #resources)
                remaining = remaining - 1
            end
            -- Breweries do not auto-flip based on resource depletion the same way;
            -- they are already flipped on build. No income award on beer consumption.
        end
    end
end


--- Remove the first tile matching `industryType` and `level` from
--- the player's unbuiltTiles stack.
local function removeTileFromUnbuilt(player, industryType, level)
    local stack = player.unbuiltTiles[industryType]
    if not stack then return nil end
    for i, tile in ipairs(stack) do
        if tile.level == level then
            table.remove(stack, i)
        end
    end
end

--- Remove the first developable (non-noDevelop) tile across all industry
--- stacks, ordered by lowest level. Returns the removed tile and its type.
local function removeLowestDevelopable(player)
    -- Collect candidates: first developable tile from each industry type
    local candidates = {}
    for industryType, stack in pairs(player.unbuiltTiles) do
        for i, tile in ipairs(stack) do
            if not tile.noDevelop then
                candidates[#candidates + 1] = {
                    industryType = industryType,
                    level        = tile.level,
                    index        = i,
                }
                break
            end
        end
    end

    if #candidates == 0 then return nil, nil end

    -- Sort by level ascending; stable by industryType as tiebreaker
    table.sort(candidates, function(a, b)
        if a.level ~= b.level then return a.level < b.level end
        return a.industryType < b.industryType
    end)

    local best = candidates[1]
    local removed = table.remove(player.unbuiltTiles[best.industryType], best.index)
    return removed, best.industryType
end

-- ============================================================
-- 1. Build
-- ============================================================

--- Execute the Build action.
--- params: { cardType, location, industryType, level, slotId }
function Actions.build(state, color, params)
    -- Step 1: Validate
    local v = Validation.canBuild(state, color, params)
    if not v.valid then
        return fail(v.reason)
    end

    local player      = GameState.getPlayer(state, color)
    local industryType = params.industryType
    local level        = params.level
    local slotId       = params.slotId

    local slot     = GameState.getSlot(state, slotId)
    local cityName = GameState.getCityForSlot(state, slotId)

    local costData = BoardData.buildingCosts[industryType][level]

    -- Step 9: For overbuilding — remove old tile from slot first.
    -- The old tile simply leaves play (no income refund etc.)
    if slot.occupant then
        slot.occupant = nil
        slot.tile     = nil
    end

    -- Step 2: Remove tile from player's unbuiltTiles
    local tile = removeTileFromUnbuilt(player, industryType, level)
    if not tile then
        return fail("Could not find tile " .. industryType .. " level " .. level
                    .. " in unbuiltTiles (internal error)")
    end

    -- Initialise the tile with its resources (mirrors Tile.newWithResources logic):
    -- fill resource tokens and auto-flip breweries.
    if tile.produces and tile.produces > 0 and tile.producesType then
        for _ = 1, tile.produces do
            tile.resources[#tile.resources + 1] = tile.producesType
        end
    end
    -- Breweries auto-flip immediately on placement
    if industryType == Constants.Industry.BREWERY then
        tile.flipped = true
    end

    -- Step 3: Place tile on board slot
    slot.occupant = color
    slot.tile     = tile

    -- Step 4: Deduct money cost
    GameState.spendMoney(state, color, costData.money)

    -- Step 5: Consume coal (nearest connected source first, then market)
    local coalNeeded = costData.coal or 0
    consumeCoal(state, color, cityName, coalNeeded)

    -- Step 6: Consume iron (any source first, then market)
    local ironNeeded = costData.iron or 0
    consumeIron(state, color, ironNeeded)

    -- Step 8: For breweries — income advance on placement (flipped = already done above)
    -- Breweries award income when they are sold/flipped; since they flip on build,
    -- we advance income now.
    if industryType == Constants.Industry.BREWERY then
        advanceIncome(state, color, tile.incomeSpaces)
    end

    -- Step 10: Update handSize (player played a card)
    GameState.playCard(state, color)

    return ok()
end

-- ============================================================
-- 2. Network
-- ============================================================

--- Execute the Network (build link) action.
--- params: { linkId, secondLinkId (optional, for double rail) }
function Actions.network(state, color, params)
    -- Step 1: Validate primary link
    local isDouble = (params.secondLinkId ~= nil)
    local v = Validation.canNetwork(state, color, {
        linkId = params.linkId,
        double = isDouble,
    })
    if not v.valid then
        return fail(v.reason)
    end

    -- If double rail, also validate the second link
    if isDouble then
        local v2 = Validation.canNetwork(state, color, {
            linkId = params.secondLinkId,
            double = false,  -- check it as a standalone single (availability)
        })
        if not v2.valid then
            return fail("Second link invalid: " .. v2.reason)
        end
    end

    local player = GameState.getPlayer(state, color)
    local era    = state.era

    -- Determine costs
    local moneyCost, coalNeeded, beerNeeded
    if era == Constants.Era.CANAL then
        moneyCost  = Constants.LinkCost.CANAL
        coalNeeded = 0
        beerNeeded = 0
    elseif isDouble then
        moneyCost  = Constants.LinkCost.DOUBLE_RAIL
        coalNeeded = 2
        beerNeeded = 1
    else
        moneyCost  = Constants.LinkCost.SINGLE_RAIL
        coalNeeded = 1
        beerNeeded = 0
    end

    -- Find a reference city for coal/beer source searching
    local linkData = BoardData.links[params.linkId]
    local refCity  = linkData.cities[1]

    -- Step 3: Deduct money
    GameState.spendMoney(state, color, moneyCost)

    -- Step 4: Consume coal
    consumeCoal(state, color, refCity, coalNeeded)

    -- Step 5: Consume beer (double rail only)
    if beerNeeded > 0 then
        consumeBeer(state, color, refCity, beerNeeded, nil)
    end

    -- Step 2: Place link(s) — set owner on board
    state.board.links[params.linkId].owner = color

    if isDouble then
        state.board.links[params.secondLinkId].owner = color
    end

    -- Step 6: Decrease linksRemaining (1 for single/canal, 2 for double)
    local linksPlaced = isDouble and 2 or 1
    player.linksRemaining = (player.linksRemaining or 0) - linksPlaced

    -- Step 7: Update handSize
    GameState.playCard(state, color)

    return ok()
end

-- ============================================================
-- 3. Sell
-- ============================================================

--- Execute the Sell action.
--- params: { slotIds = { "slotId1", ... }, merchantName = "Shrewsbury" }
function Actions.sell(state, color, params)
    -- Step 1: Validate
    local v = Validation.canSell(state, color, params)
    if not v.valid then
        return fail(v.reason)
    end

    local slotIds     = params.slotIds or { params.slotId }
    local merchantName = params.merchantName  -- may be nil

    -- Step 2: For each building, consume beer, flip tile, advance income
    for _, slotId in ipairs(slotIds) do
        local slot = GameState.getSlot(state, slotId)
        local tile = slot.tile
        local cityName = GameState.getCityForSlot(state, slotId)

        -- 2a. Consume required beer
        local beerNeeded = tile.beerToSell or 0
        if beerNeeded > 0 then
            consumeBeer(state, color, cityName, beerNeeded, merchantName)
        end

        -- 2b. Flip the tile
        tile.flipped = true

        -- 2c. Advance income track
        advanceIncome(state, color, tile.incomeSpaces)
    end

    -- Step 3: Process merchant bonus if a merchant city was involved
    if merchantName then
        local merchant = state.board.merchants[merchantName]
        if merchant and merchant.bonus then
            local bonus = merchant.bonus
            local player = GameState.getPlayer(state, color)
            if bonus.type == "vp" then
                player.vp = (player.vp or 0) + (bonus.value or 0)
            elseif bonus.type == "money" then
                GameState.gainMoney(state, color, bonus.value or 0)
            elseif bonus.type == "income_advance" then
                advanceIncome(state, color, bonus.value or 0)
            elseif bonus.type == "develop_free" then
                -- Grant a free develop: flag for the caller to handle, or
                -- remove one developable tile from unbuiltTiles without iron cost.
                local count = bonus.value or 1
                for _ = 1, count do
                    removeLowestDevelopable(player)
                end
            end
        end
    end

    -- Step 4: Update handSize
    GameState.playCard(state, color)

    return ok()
end

-- ============================================================
-- 4. Develop
-- ============================================================

--- Execute the Develop action.
--- params: { count = 1 or 2 }
function Actions.develop(state, color, params)
    -- Step 1: Validate
    local v = Validation.canDevelop(state, color, params)
    if not v.valid then
        return fail(v.reason)
    end

    local count  = params.count or 1
    local player = GameState.getPlayer(state, color)

    -- Steps 2 & 3: For each tile to develop, consume 1 iron then remove tile.
    for _ = 1, count do
        -- Consume 1 iron (buildings first, then market)
        consumeIron(state, color, 1)
        -- Remove lowest-level non-noDevelop tile from unbuiltTiles
        removeLowestDevelopable(player)
    end

    -- Step 4: Update handSize
    GameState.playCard(state, color)

    return ok()
end

-- ============================================================
-- 5. Loan
-- ============================================================

--- Execute the Loan action.
function Actions.loan(state, color)
    -- Step 1: Validate
    local v = Validation.canLoan(state, color)
    if not v.valid then
        return fail(v.reason)
    end

    local player = GameState.getPlayer(state, color)

    -- Step 2: Gain £LOAN_AMOUNT
    GameState.gainMoney(state, color, Constants.LOAN_AMOUNT)

    -- Step 3: Decrease income by LOAN_INCOME_PENALTY levels
    local newLevel, newSpace = IncomeTrack.decreaseLevels(
        player.incomeLevel, player.incomeSpace, Constants.LOAN_INCOME_PENALTY)
    player.incomeLevel = newLevel
    player.incomeSpace = newSpace

    -- Step 4: Update handSize (player played a card)
    GameState.playCard(state, color)

    return ok()
end

-- ============================================================
-- 6. Scout
-- ============================================================

--- Execute the Scout action.
function Actions.scout(state, color)
    -- Step 1: Validate
    local v = Validation.canScout(state, color)
    if not v.valid then
        return fail(v.reason)
    end

    local player = GameState.getPlayer(state, color)

    -- Steps 2 & 3: Net handSize change is -1 (lost 3 cards, gained 2 wilds).
    -- The card played counts as -1, the 2 discarded are -2, gaining 2 wilds = +2.
    GameState.playCard(state, color)       -- lose 1 (played card)
    player.handSize = player.handSize - 2  -- lose 2 (discarded)
    player.handSize = player.handSize + 2  -- gain 2 wild cards
    player.hasWilds = true

    -- Step 4: Decrease wildSupply
    state.wildSupply.location = state.wildSupply.location - 1
    state.wildSupply.industry = state.wildSupply.industry - 1

    -- Step 5: Mark scout used this round
    player.scoutUsedThisRound = true

    return ok()
end


-- ===== Module: Scoring =====

Scoring = {}

-- ============================================================
-- Building VP Scoring
-- ============================================================

--- Score VP for all flipped buildings owned by a player.
--- A building scores its VP value only if:
---   - The player occupies the slot
---   - The tile is placed and flipped
---
--- @param state table  Game state
--- @param color string  Player color
--- @return number  Total VP from flipped buildings
function Scoring.scoreBuildingVP(state, color)
    local total = 0
    GameState.forEachSlot(state, function(cityName, slot)
        if slot.occupant == color and slot.tile and slot.tile.flipped then
            total = total + (slot.tile.vp or 0)
        end
    end)
end

-- ============================================================
-- Link VP Scoring
-- ============================================================

--- Score VP for all links owned by a player.
--- For each link owned by the player, count the sum of link icons
--- on flipped buildings in both adjacent cities.
---
--- @param state table  Game state
--- @param color string  Player color
--- @return number  Total VP from links (based on link icons in adjacent cities)
function Scoring.scoreLinkVP(state, color)
    local total = 0
    for linkId, link in pairs(state.board.links) do
        if link.owner == color then
            local linkData = BoardData.links[linkId]
            local cityList = linkData and linkData.cities or {}

            for _, cityName in ipairs(cityList) do
                local city = state.board.cities[cityName]
                if city and city.slots then
                    for _, slot in ipairs(city.slots) do
                        if slot.tile and slot.tile.flipped then
                            total = total + (slot.tile.linkIcons or 0)
                        end
                    end
                end
            end
        end
    end
end

-- ============================================================
-- Income VP Scoring
-- ============================================================

--- Score income VP (only at end of game / end of rail era).
--- The player's current income level directly equals VP (can be negative).
---
--- @param state table  Game state
--- @param color string  Player color
--- @return number  Income level (which equals VP at end of game)
function Scoring.scoreIncomeVP(state, color)
    return GameState.getPlayer(state, color).incomeLevel
end

-- ============================================================
-- End-of-Era Scoring
-- ============================================================

--- Execute end-of-era scoring for all players.
--- Calculates building VP, link VP, and optionally income VP.
--- Updates each player's total VP and returns a detailed breakdown.
---
--- @param state table  Game state
--- @param isFinal boolean  If true, includes income VP (end of rail era)
--- @return table  Scoring results for each player color
function Scoring.scoreEndOfEra(state, isFinal)
    local results = {}
    for _, color in ipairs(state.turnOrder) do
        local buildingVP = Scoring.scoreBuildingVP(state, color)
        local linkVP = Scoring.scoreLinkVP(state, color)
        local incomeVP = isFinal and Scoring.scoreIncomeVP(state, color) or 0
        local totalEraVP = buildingVP + linkVP + incomeVP

        local p = GameState.getPlayer(state, color)
        p.vp = p.vp + totalEraVP

        results[color] = {
            buildingVP = buildingVP,
            linkVP = linkVP,
            incomeVP = incomeVP,
            totalEraVP = totalEraVP,
            totalVP = p.vp,
        }
    end
end

-- ============================================================
-- Final Ranking / Winner Determination
-- ============================================================

--- Determine final ranking of all players.
--- Tiebreaker order:
---   1. VP (higher is better)
---   2. Income level (higher is better)
---   3. Remaining money (higher is better)
---   4. Shared victory (indicated by equal ranking)
---
--- @param state table  Game state
--- @return table  List of ranking entries { color, vp, incomeLevel, money }
function Scoring.determineWinner(state)
    local ranking = {}
    for _, color in ipairs(state.turnOrder) do
        local p = GameState.getPlayer(state, color)
        ranking[#ranking + 1] = {
            color = color,
            vp = p.vp,
            incomeLevel = p.incomeLevel,
            money = p.money,
        }
    end
    table.sort(ranking, function(a, b)
        if a.vp ~= b.vp then return a.vp > b.vp end
        if a.incomeLevel ~= b.incomeLevel then return a.incomeLevel > b.incomeLevel end
        return a.money > b.money
    end)
end


-- ===== Module: EraTransition =====

EraTransition = {}

-- ============================================================
-- End-of-Era Detection
-- ============================================================

--- Check if the current era is over.
--- Condition: deck is empty AND all players have 0 cards in hand
---
--- @param state table  Game state
--- @return boolean  True if the era is over
function EraTransition.isEraOver(state)
    if not state.deckEmpty then return false end
    for _, color in ipairs(state.turnOrder) do
        local p = GameState.getPlayer(state, color)
        if p.handSize > 0 then return false end
    end
end

-- ============================================================
-- Canal-to-Rail Transition
-- ============================================================

--- Execute the full canal-to-rail transition.
--- Handles scoring, board cleanup, era switch, and player reset.
---
--- @param state table  Game state
function EraTransition.transition(state)
    -- 1. Score canal era (mid-game scoring: buildings + links, no income)
    Scoring.scoreEndOfEra(state, false)

    -- 2. Remove ALL placed links (during canal era, only canal links can be placed)
    for linkId, link in pairs(state.board.links) do
        if link.owner then
            link.owner = nil
            link.tileGUID = nil
        end
    end

    -- 3. Remove ALL Level 1 buildings from the board
    GameState.forEachSlot(state, function(cityName, slot)
        if slot.tile and slot.tile.level == 1 then
            slot.tile = nil
            slot.occupant = nil
        end
    end)

    -- 4. Switch era
    state.era = Constants.Era.RAIL

    -- 5. Reset round counter
    state.round = 1

    -- 6. Rebuild slot index (some slots may have changed)
    -- Actually slotIndex references are stable, no rebuild needed

    -- 7. Replenish merchant beer (each active merchant slot gets 1 beer)
    if state.board.merchants then
        for _, merchant in pairs(state.board.merchants) do
            if merchant.slots then
                for i = 1, #merchant.slots do
                    merchant.slots[i].filled = false
                    merchant.slots[i].tileGUID = nil
                end
            end
        end
    end

    -- 8. Reset market supplies to initial values
    state.coalMarket.supply = Constants.INITIAL_COAL_SUPPLY
    state.ironMarket.supply = Constants.INITIAL_IRON_SUPPLY

    -- 9. Reset wild supply
    state.wildSupply.location = Constants.WILD_SUPPLY_COUNT
    state.wildSupply.industry = Constants.WILD_SUPPLY_COUNT

    -- 10. Reset deck state (TTS layer will handle actual card shuffling)
    state.deckEmpty = false

    -- 11. Reset player states for new era
    for _, color in ipairs(state.turnOrder) do
        local p = GameState.getPlayer(state, color)
        p.handSize = Constants.INITIAL_HAND_SIZE  -- TTS will deal cards
        p.hasWilds = false
        p.spentThisRound = 0
        p.scoutUsedThisRound = false
    end

    -- 12. Set actions for first turn (rail era has NO first-round exception — always 2 actions)
    state.currentPlayerIdx = 1
    state.actionsRemaining = 2
end


