-- Get a localized string
-- locale: "en" or "zh-TW"
function Lang.get(key, locale)
    local strings = Lang.strings[locale] or Lang.strings["en"]
    return strings[key] or Lang.strings["en"][key] or ("?" .. key .. "?")
end

-- Format a localized string with parameter substitution
-- params: { player = "Red", amount = 15 }
-- Template uses {key} syntax: "Player {player} spent £{amount}"
function Lang.format(key, locale, params)
    local str = Lang.get(key, locale)
    if params then
        for k, v in pairs(params) do
            str = str:gsub("{" .. k .. "}", tostring(v))
        end
    end
end


-- ===== Module: SnapMap =====
SnapMap = {}

SnapMap.byTag = {}      -- tag string → { position, rotation, snapIndex }
SnapMap.bySlotId = {}   -- "Birmingham_cotton_1" → snap data
SnapMap.byLinkId = {}   -- "Birmingham-Coventry" → snap data

--- Scan a board object's snap points and build all mappings
-- Snap point tags follow format:
--   "city_Birmingham_cotton_1" for building slots
--   "link_Birmingham-Coventry" for route links
--   "market_coal_3" for market positions
function SnapMap.buildFromObject(boardObject)
    SnapMap.byTag = {}
    SnapMap.bySlotId = {}
    SnapMap.byLinkId = {}

    local snaps = boardObject.getSnapPoints()
    for i, snap in ipairs(snaps) do
        local tag = snap.tags and snap.tags[1] or nil
        if tag then
            local data = {
                position = boardObject.positionToWorld(snap.position),
                rotation = snap.rotation,
                snapIndex = i,
                tag = tag,
            }
            SnapMap.byTag[tag] = data

            -- Parse tag to categorize
            if tag:sub(1, 5) == "city_" then
                -- "city_Birmingham_cotton_1" → slotId = "Birmingham_cotton_1"
                local slotId = tag:sub(6)
                SnapMap.bySlotId[slotId] = data
            elseif tag:sub(1, 5) == "link_" then
                local linkId = tag:sub(6)
                SnapMap.byLinkId[linkId] = data
            end
        end
    end
end

--- Get world position for a building slot
function SnapMap.getPositionForSlot(slotId)
    local data = SnapMap.bySlotId[slotId]
    return data and data.position or nil
end

--- Get world position for a route link
function SnapMap.getPositionForLink(linkId)
    local data = SnapMap.byLinkId[linkId]
    return data and data.position or nil
end

--- Find the nearest game position to a world coordinate
-- Returns { type = "slot"|"link", id = "..." } or nil
function SnapMap.findNearestPosition(worldPos, threshold)
    local nearest = nil
    local nearestDist = threshold or 2.0

    for slotId, data in pairs(SnapMap.bySlotId) do
        local dist = SnapMap._distance(worldPos, data.position)
        if dist < nearestDist then
            nearestDist = dist
            nearest = { type = "slot", id = slotId }
        end
    end

    for linkId, data in pairs(SnapMap.byLinkId) do
        local dist = SnapMap._distance(worldPos, data.position)
        if dist < nearestDist then
            nearestDist = dist
            nearest = { type = "link", id = linkId }
        end
    end

end

--- Euclidean distance between two positions (tables with x,y,z or [1],[2],[3])
function SnapMap._distance(a, b)
    local dx = (a.x or a[1]) - (b.x or b[1])
    local dy = (a.y or a[2]) - (b.y or b[2])
    local dz = (a.z or a[3]) - (b.z or b[3])
    return math.sqrt(dx*dx + dy*dy + dz*dz)
end


-- ===== Module: ObjectManager =====
ObjectManager = {}

ObjectManager.guids = {
    mainBoard = nil,
    drawDeck = nil,
    discardZone = nil,
    playerBoards = {},     -- { ["Red"] = GUID, ... }
    playerHandZones = {},  -- { ["Red"] = GUID, ... }
    wildLocationSupply = nil,
    wildIndustrySupply = nil,
    languageToggle = nil,
    resourceBags = {},     -- { coal = GUID, iron = GUID, beer = GUID }
    moneyBags = {},        -- { ["1"] = GUID, ["5"] = GUID, ["15"] = GUID }
}

--- Scan all objects on the table and identify them by Name
-- Expected object names:
--   "Main Board", "Draw Deck", "Discard Zone"
--   "Player Board Red", "Player Board Blue", etc.
--   "Hand Zone Red", "Hand Zone Blue", etc.
--   "Wild Location Supply", "Wild Industry Supply"
--   "Language Toggle"
--   "Coal Bag", "Iron Bag", "Beer Bag"
--   "Money 1 Bag", "Money 5 Bag", "Money 15 Bag"
function ObjectManager.scanTable()
    for _, obj in ipairs(getAllObjects()) do
        local name = obj.getName()
        if name == "Main Board" then
            ObjectManager.guids.mainBoard = obj.getGUID()
        elseif name == "Draw Deck" then
            ObjectManager.guids.drawDeck = obj.getGUID()
        elseif name == "Discard Zone" then
            ObjectManager.guids.discardZone = obj.getGUID()
        elseif name == "Wild Location Supply" then
            ObjectManager.guids.wildLocationSupply = obj.getGUID()
        elseif name == "Wild Industry Supply" then
            ObjectManager.guids.wildIndustrySupply = obj.getGUID()
        elseif name == "Language Toggle" then
            ObjectManager.guids.languageToggle = obj.getGUID()
        elseif name == "Coal Bag" then
            ObjectManager.guids.resourceBags.coal = obj.getGUID()
        elseif name == "Iron Bag" then
            ObjectManager.guids.resourceBags.iron = obj.getGUID()
        elseif name == "Beer Bag" then
            ObjectManager.guids.resourceBags.beer = obj.getGUID()
        elseif name == "Money 1 Bag" then
            ObjectManager.guids.moneyBags["1"] = obj.getGUID()
        elseif name == "Money 5 Bag" then
            ObjectManager.guids.moneyBags["5"] = obj.getGUID()
        elseif name == "Money 15 Bag" then
            ObjectManager.guids.moneyBags["15"] = obj.getGUID()
        else
            -- Check for player-specific objects
            for _, color in ipairs({"Red", "Blue", "Yellow", "Green"}) do
                if name == "Player Board " .. color then
                    ObjectManager.guids.playerBoards[color] = obj.getGUID()
                elseif name == "Hand Zone " .. color then
                    ObjectManager.guids.playerHandZones[color] = obj.getGUID()
                end
            end
        end
    end
end

--- Get an object by role name
function ObjectManager.getObject(role)
    local guid = ObjectManager.guids[role]
    if type(guid) == "string" then
        return getObjectFromGUID(guid)
    end
end

--- Get a player board by color
function ObjectManager.getPlayerBoard(color)
    local guid = ObjectManager.guids.playerBoards[color]
    return guid and getObjectFromGUID(guid)
end

--- Spawn a resource from its bag at the given position
function ObjectManager.spawnResource(resourceType, position)
    local bagGUID = ObjectManager.guids.resourceBags[resourceType]
    if not bagGUID then return nil end
    local bag = getObjectFromGUID(bagGUID)
    if not bag then return nil end
    return bag.takeObject({ position = position })
end

--- Spawn money from the appropriate bag at the given position
function ObjectManager.spawnMoney(denomination, position)
    local key = tostring(denomination)
    local bagGUID = ObjectManager.guids.moneyBags[key]
    if not bagGUID then return nil end
    local bag = getObjectFromGUID(bagGUID)
    if not bag then return nil end
    return bag.takeObject({ position = position })
end

--- Move an object to a position with optional rotation
function ObjectManager.moveTo(obj, position, rotation)
    if not obj then return end
    obj.setPositionSmooth(position)
    if rotation then obj.setRotationSmooth(rotation) end
end

--- Destroy an object
function ObjectManager.destroy(obj)
    if obj and not obj.isDestroyed() then obj.destruct() end
end

--- Lock an object
function ObjectManager.lock(obj)
    if obj then obj.setLock(true) end
end

--- Unlock an object
function ObjectManager.unlock(obj)
    if obj then obj.setLock(false) end
end

--- Save GUIDs for persistence
function ObjectManager.saveGUIDs()
    return ObjectManager.guids
end

--- Load saved GUIDs
function ObjectManager.loadGUIDs(savedGuids)
    if savedGuids then
        ObjectManager.guids = savedGuids
    end
end


-- ===== Module: CardManager =====
--- CardManager.lua
-- Handles all TTS card/deck operations including dealing, discarding, and supply management

CardManager = {}

--- Build the initial draw deck for player count
-- Removes location cards for cities not in the game
-- @param state Game state object
-- @param deckObj TTS deck object
function CardManager.buildDeck(state, deckObj)
    if #removedCities > 0 then
        local cards = deckObj.getObjects()  -- get list of cards in deck
        for i = #cards, 1, -1 do
            local card = cards[i]
            for _, city in ipairs(removedCities) do
                if card.name and card.name:find(city) then
                    deckObj.takeObject({
                        index = card.index,
                        position = {0, -5, 0},  -- off-table
                        callback_function = function(obj) obj.destruct() end,
                    })
                    break
                end
            end
        end
    end
    Wait.time(function() deckObj.shuffle() end, 0.5)
end

--- Deal cards to all players (up to hand size 8)
-- @param state Game state object
function CardManager.dealToAll(state)
    local deckObj = ObjectManager.getObject("drawDeck")
    if not deckObj then return end
    for _, color in ipairs(state.turnOrder) do
        local p = GameState.getPlayer(state, color)
        local toDeal = Constants.INITIAL_HAND_SIZE - (p.handSize or 0)
        if toDeal > 0 then
            deckObj.deal(toDeal, color)
            p.handSize = Constants.INITIAL_HAND_SIZE
        end
    end
end

--- Parse a played card to determine its type
-- Card naming convention: "Location: Birmingham", "Industry: Cotton", "Wild Location", "Wild Industry"
-- @param cardObj TTS card object
-- @return Table with cardType and relevant data (location or industryType), or nil if unrecognized
function CardManager.parseCard(cardObj)
    local name = cardObj.getName()
    if name:find("^Wild Location") then
        return { cardType = Constants.CardType.WILD_LOCATION }
    elseif name:find("^Wild Industry") then
        return { cardType = Constants.CardType.WILD_INDUSTRY }
    elseif name:find("^Location: ") then
        local city = name:match("^Location: (.+)")
        return { cardType = Constants.CardType.LOCATION, location = city }
    elseif name:find("^Industry: ") then
        local industry = name:match("^Industry: (.+)")
        return { cardType = Constants.CardType.INDUSTRY, industryType = industry:lower() }
    end
end

--- Move a card to the discard pile
-- @param cardObj TTS card object
function CardManager.discard(cardObj)
    local discardZone = ObjectManager.getObject("discardZone")
    if discardZone then
        cardObj.setPositionSmooth(discardZone.getPosition() + Vector(0, 1, 0))
    end
end

--- Return a wild card to its supply pile
-- @param cardObj TTS card object
-- @param wildType Card type (Constants.CardType.WILD_LOCATION or WILD_INDUSTRY)
function CardManager.returnWildToSupply(cardObj, wildType)
    local supplyKey = (wildType == Constants.CardType.WILD_LOCATION)
        and "wildLocationSupply" or "wildIndustrySupply"
    local supply = ObjectManager.getObject(supplyKey)
    if supply then
        cardObj.setPositionSmooth(supply.getPosition() + Vector(0, 0.5, 0))
    end
end

--- Give wild cards to a player (for Scout action)
-- @param playerColor Player color string
function CardManager.giveWilds(playerColor)
    local locSupply = ObjectManager.getObject("wildLocationSupply")
    local indSupply = ObjectManager.getObject("wildIndustrySupply")

    if locSupply and locSupply.getQuantity() > 0 then
        locSupply.deal(1, playerColor)
    end
    if indSupply and indSupply.getQuantity() > 0 then
        indSupply.deal(1, playerColor)
    end
end

--- Check if the draw deck is empty
-- @return Boolean true if deck is empty
function CardManager.isDeckEmpty()
    local deckObj = ObjectManager.getObject("drawDeck")
    if not deckObj then return true end
    if deckObj.type == "Deck" then return deckObj.getQuantity() <= 0 end
    if deckObj.type == "Card" then return false end  -- single card left
end

--- Rebuild deck for rail era transition
-- Collects all cards from discard zone and prepares for rail era
-- @param state Game state object
function CardManager.rebuildDeckForRailEra(state)
    -- Collect all cards from discard zone
    local discardZone = ObjectManager.getObject("discardZone")
    if not discardZone then return end

    -- Get objects in the zone
    local objects = discardZone.getObjects and discardZone.getObjects() or {}
    -- Group them into a deck, then build and shuffle
    -- Note: actual implementation depends on how TTS zones work
    -- This is a simplified version
    Wait.time(function()
        local deckObj = ObjectManager.getObject("drawDeck")
        if deckObj then
            CardManager.buildDeck(state, deckObj)
        end
    end, 1.0)
end

--- Refill a player's hand to 8 cards
-- @param state Game state object
-- @param color Player color string
function CardManager.refillHand(state, color)
    local deckObj = ObjectManager.getObject("drawDeck")
    if not deckObj then return end
    local p = GameState.getPlayer(state, color)
    local toDeal = Constants.INITIAL_HAND_SIZE - (p.handSize or 0)
    if toDeal > 0 and deckObj.getQuantity() >= toDeal then
        deckObj.deal(toDeal, color)
        p.handSize = Constants.INITIAL_HAND_SIZE
    end
end


-- ===== Module: Highlights =====
--- Highlights.lua
-- Provides visual highlighting on TTS objects for legal moves
-- Spawns temporary marker tokens and applies highlight glow to objects

Highlights = {}

-- Active highlights tracking for cleanup
Highlights.activeHighlights = {
    markers = {},      -- list of spawned temporary marker objects
    objects = {},      -- list of highlighted game objects
}

--- Highlight a single object with a colored glow
-- @param obj TTS object to highlight
-- @param color TTS color string or RGB table (default green)
function Highlights.highlightObject(obj, color)
    if not obj or obj.isDestroyed() then return end

    local colorTable = color or {0, 1, 0}  -- default green
    -- Convert color string to RGB if needed
    if type(color) == "string" then
        colorTable = Highlights._colorStringToRGB(color)
    end

    obj.highlightOn(colorTable, -1)  -- -1 = permanent until cleared
    table.insert(Highlights.activeHighlights.objects, obj)
end

--- Spawn a temporary marker token at a world position
-- @param position Vector or table {x, y, z}
-- @param color TTS color string or RGB table (default green)
-- @return Spawned object or nil
function Highlights._spawnMarker(position, color)
    local colorTable = color or {0, 1, 0}  -- default green
    if type(color) == "string" then
        colorTable = Highlights._colorStringToRGB(color)
    end

    -- Spawn a small custom token as a visual marker
    local marker = spawnObject({
        type = "Custom_Token",
        position = position,
        rotation = {0, 0, 0},
        scale = {0.5, 0.5, 0.5},
    })

    if marker then
        marker.setColorTint(colorTable)
        marker.setLock(true)  -- prevent accidental movement
        table.insert(Highlights.activeHighlights.markers, marker)
    end

end

--- Convert color string to RGB table
-- @param colorStr TTS color name ("Red", "Green", "Blue", "Yellow", "White", "Black")
-- @return RGB table {r, g, b}
function Highlights._colorStringToRGB(colorStr)
    local colors = {
        Red = {1, 0, 0},
        Green = {0, 1, 0},
        Blue = {0, 0, 1},
        Yellow = {1, 1, 0},
        White = {1, 1, 1},
        Black = {0, 0, 0},
    }
    return colors[colorStr] or {0, 1, 0}  -- default to green
end

--- Show valid build spots for a given card
-- Checks each slot via Validation.canBuild and highlights valid ones
-- @param state Game state object
-- @param color Player color string
-- @param cardInfo Table with cardType, location (for location cards), industryType, level
function Highlights.showValidBuildSpots(state, color, cardInfo)
    Highlights.clearAll()

    local validSlots = {}

    -- Iterate through all slots and check if build is valid
    GameState.forEachSlot(state, function(slotId, slot)
        local buildParams = {
            cardType = cardInfo.cardType,
            location = cardInfo.location,
            industryType = cardInfo.industryType,
            level = cardInfo.level,
            slotId = slotId,
        }

        local result = Validation.canBuild(state, color, buildParams)
        if result.valid then
            validSlots[#validSlots + 1] = slotId

            -- Get snap point position for this slot from SnapMap
            local snapPos = SnapMap.getPositionForSlot(slotId)
            if snapPos then
                Highlights._spawnMarker(snapPos, "Green")
            end
        end
    end)

    -- Brief feedback to player
    if #validSlots == 0 then
        printToColor("No valid build spots for this card.", color, {1, 1, 0})
    else
        printToColor("Found " .. #validSlots .. " valid build spot(s). (Green markers)", color, {0, 1, 0})
    end
end

--- Show valid link spots (network action)
-- Checks each link via Validation.canNetwork and highlights valid ones
-- @param state Game state object
-- @param color Player color string
function Highlights.showValidLinkSpots(state, color)
    Highlights.clearAll()

    local validLinks = {}

    -- Iterate through all links and check if network is valid
    for linkId, link in pairs(state.board.links) do
        -- Skip already-owned links
        if not link.owner then
            local linkParams = {
                linkId = linkId,
                double = false,  -- show single rail for now
            }

            local result = Validation.canNetwork(state, color, linkParams)
            if result.valid then
                validLinks[#validLinks + 1] = linkId

                -- Get snap point position for this link from SnapMap
                local snapPos = SnapMap.getPositionForLink(linkId)
                if snapPos then
                    Highlights._spawnMarker(snapPos, "Blue")
                end
            end
        end
    end

    -- Brief feedback to player
    if #validLinks == 0 then
        printToColor("No valid link spots available.", color, {1, 1, 0})
    else
        printToColor("Found " .. #validLinks .. " valid link spot(s). (Blue markers)", color, {0, 0, 1})
    end
end

--- Show all sellable buildings for current player
-- Finds all buildings that can be sold and highlights them
-- @param state Game state object
-- @param color Player color string
function Highlights.showSellableBuildings(state, color)
    Highlights.clearAll()

    local sellableCount = 0

    -- Iterate through all slots belonging to this player
    GameState.forEachSlot(state, function(slotId, slot)
        if slot.occupant == color and slot.tile then
            local sellParams = {
                slotId = slotId,
            }

            local result = Validation.canSell(state, color, sellParams)
            if result.valid then
                sellableCount = sellableCount + 1

                -- Try to get the actual TTS object for this building
                -- For now, we'll spawn a marker at the snap position
                local snapPos = SnapMap.getPositionForSlot(slotId)
                if snapPos then
                    Highlights._spawnMarker(snapPos, "Yellow")
                end
            end
        end
    end)

    -- Brief feedback to player
    if sellableCount == 0 then
        printToColor("No buildings available to sell.", color, {1, 1, 0})
    else
        printToColor("Found " .. sellableCount .. " sellable building(s). (Yellow markers)", color, {1, 1, 0})
    end
end

--- Clear all active highlights and temporary markers
-- Removes all spawned markers and highlights from objects
function Highlights.clearAll()
    -- Destroy all temporary markers
    for _, marker in ipairs(Highlights.activeHighlights.markers) do
        if marker and not marker.isDestroyed() then
            marker.destruct()
        end
    end
    Highlights.activeHighlights.markers = {}

    -- Remove highlights from all objects
    for _, obj in ipairs(Highlights.activeHighlights.objects) do
        if obj and not obj.isDestroyed() then
            obj.highlightOff()
        end
    end
    Highlights.activeHighlights.objects = {}
end


